class Writer:
 def __init__(self,index,title,ru,landscape=False):
  self.d=Document(); self.lines=[]; self.index=index; self.pending_page=False
  sec=self.d.sections[0]
  if landscape:
   sec.orientation=WD_ORIENT.LANDSCAPE; sec.page_width=Cm(29.7); sec.page_height=Cm(21)
  else: sec.page_width=Cm(21); sec.page_height=Cm(29.7)
  sec.top_margin=Cm(1.5); sec.bottom_margin=Cm(1.5); sec.left_margin=Cm(1.7); sec.right_margin=Cm(1.7)
  sec.header_distance=Cm(.6); sec.footer_distance=Cm(.6)
  self.width=(sec.page_width-sec.left_margin-sec.right_margin)/360000
  for name in ['Normal','Title','Subtitle','Heading 1','Heading 2','Heading 3','Caption']:
   s=self.d.styles[name]; s.font.name='Arial'; s.font.color.rgb=RGBColor(0,0,0)
   s.element.get_or_add_rPr().append(self.font_element())
   s.paragraph_format.space_after=Pt(5)
   snap=OxmlElement('w:snapToGrid');snap.set(qn('w:val'),'0');s.element.get_or_add_pPr().append(snap)
  norm=self.d.styles['Normal']; norm.font.size=Pt(10.5); norm.paragraph_format.line_spacing=Pt(14); norm.paragraph_format.space_after=Pt(4)
  for name,size in [('Title',22),('Heading 1',15),('Heading 2',12),('Heading 3',11)]:
   self.d.styles[name].font.size=Pt(size)
   self.d.styles[name].paragraph_format.space_before=Pt(9)
  self.d.styles['Title'].paragraph_format.space_before=Pt(0)
  self.d.styles['Heading 2'].paragraph_format.space_before=Pt(3)
  self.d.styles['Heading 3'].paragraph_format.space_before=Pt(2)
  for border in self.d.styles.element.xpath('.//w:pBdr'):
   border.getparent().remove(border)
  self.d.core_properties.title=title+' '+ru
  self.d.core_properties.subject='StudySpace Product Backlog v1'
  self.d.core_properties.author='StudySpace'
  self.p(title,'Title'); self.p(ru,'Subtitle')
  self.p(f'Doc-ID SS-PB-0{index+1}  |  Version v1  |  2026-10-14  |  DRAFT')
  self.p('来源图片 / Исходное изображение  '+SOURCES[index],size=8)
  self.bp(SCOPE_TEXT)
  f=self.d.sections[0].footer.paragraphs[0]; f.alignment=WD_ALIGN_PARAGRAPH.RIGHT
  run=f.add_run('StudySpace  v1  |  '); run.font.size=Pt(8)
  fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); f._p.append(fld)
 @staticmethod
 def font_element():
  el=OxmlElement('w:rFonts')
  for a in ['ascii','hAnsi','cs']:el.set(qn('w:'+a),'Arial')
  el.set(qn('w:eastAsia'),'PingFang SC'); return el
 def p(self,text='',style=None,size=None):
  p=self.d.add_paragraph(style=style); r=p.add_run(text)
  if self.pending_page:
   p.paragraph_format.page_break_before=True;self.pending_page=False
  if size:r.font.size=Pt(size)
  self.lines.append(text); return p
 def bp(self,x): self.p(x['zh-CN']); self.p(x['ru-RU'])
 def h(self,n,zh,ru):self.p(f'{n} {zh}','Heading 1');self.p(f'{n} {ru}','Heading 2')
 def page(self): self.pending_page=True; self.lines.append('\n---\n')
 def table(self,headers,rows,widths=None,size=9):
  t=self.d.add_table(rows=1,cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
  if widths is None: widths=[self.width/len(headers)]*len(headers)
  for c,w,h in zip(t.columns,widths,headers):c.width=Cm(w)
  for i,h in enumerate(headers):t.rows[0].cells[i].text=h
  for row in rows:
   cells=t.add_row().cells
   for c,tx in zip(cells,row):c.text=str(tx)
  for ri,row in enumerate(t.rows):
   pr=row._tr.get_or_add_trPr(); no=OxmlElement('w:cantSplit');pr.append(no)
   if ri==0:
    repeat=OxmlElement('w:tblHeader');pr.append(repeat)
   for ci,c in enumerate(row.cells):
    c.width=Cm(widths[ci]);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
    props=c._tc.get_or_add_tcPr()
    margins=OxmlElement('w:tcMar')
    for side in ['top','bottom','left','right']:
     e=OxmlElement('w:'+side);e.set(qn('w:w'),'60' if side in ['top','bottom'] else '90');e.set(qn('w:type'),'dxa');margins.append(e)
    props.append(margins)
    borders=OxmlElement('w:tcBorders')
    for side in ['top','left','bottom','right']:
     e=OxmlElement('w:'+side);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');borders.append(e)
    props.append(borders)
    sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'DFE9F2' if ri==0 else ('F5F7FA' if ri%2==0 else 'FFFFFF'));props.append(sh)
    for p in c.paragraphs:
     p.paragraph_format.space_after=Pt(1);p.paragraph_format.space_before=Pt(1);p.paragraph_format.line_spacing=Pt(size*1.4)
     snap=OxmlElement('w:snapToGrid');snap.set(qn('w:val'),'0');p._p.get_or_add_pPr().append(snap)
     for r in p.runs:r.font.size=Pt(size);r.font.bold=ri==0;r.font.color.rgb=RGBColor(0,0,0)
  self.lines.append('| '+' | '.join(headers)+' |')
  self.lines.extend('| '+' | '.join(str(a).replace('\n',' / ') for a in r)+' |' for r in rows)
  gap=self.p('',size=3);gap.paragraph_format.line_spacing=Pt(3);gap.paragraph_format.space_after=Pt(3);gap.paragraph_format.space_before=Pt(0)
  return t
 def save(self):
  path=OUT/FILES[self.index]
  if path.exists() and '--revise' not in sys.argv: raise RuntimeError('Refuse to overwrite existing deliverable: '+str(path))
  self.d.save(path);path.with_suffix('.md').write_text('\n\n'.join(self.lines),encoding='utf-8')
  return path

